<p>能量决定强度：普攻和未被强化的技能命中都充能，能量≥30时技能获得强化——一技能回血翻倍、二技能带击飞、大招护盾+电弧。满能量进场一套连招能打掉脆皮70%血量，能量空了就是超级兵。</p>
