  <div class="tip-box">打法总纲：前期（1-4级）羸弱，稳定补刀不死即可，别硬拼。4级质变，有附魔就有真伤。口诀"二吸盾、一附魔、A打伤"三者缺一不可。团战大招优先落敌方站位密集处，落地后站场内吃双抗持续真伤。S44 纯战边回暖利好吕布，但高分段他仍偏弱（胜率46%），属低分战神——想上分优先选更稳的版本答案。</div>
