  <p>重做后的扁鹊不再是"贴脸蹭毒的移动血包"，而是<b>峡谷唯一自带复活的法核</b>：敌我双印记体系（敌方叠毒、我方叠奶），大招引爆全场印记并<b>真实斩杀</b>，被动还能把死掉的队友直接拉回来。他现在是<b>半法核 + 半辅助的战术位</b>。</p>
