  <p>女娲是<b>峡谷唯一能"建墙"的法师</b>：二技能凭空造出实体矩阵空间挡住敌方英雄，三技能能无目标限制地把自己传送到视野内任意位置。她赢比赛的方式不是打出多少伤害，而是<b>用矩阵把战场切成两半，让对方永远只能以少打多</b>。</p>
