    <div class="desc">持续倾泻法力弹幕，对命中敌人造成 <code>70(+9%法强)</code> 法术伤害，期间自身增加 30% 移速；法力足够时产生额外子弹（每颗耗 50 法力，造成等额伤害并回复 <code>80(+1.2%额外最大生命)</code> 生命）。可 3 秒持续按压释放。CD <code>12.5→10</code> 秒。</div>
