  <tr><td>出装（CD 量变质变流）</td><td>冷静之靴 → 圣杯 → 回响之杖 → 无象神器·凝神 → 博学者之怒 → 虚无法杖</td><td>圣杯保蓝+冷却，无象神器大招永动，适合瞄不准玩家</td></tr>
