  <div class="tip-box"><b>版本地位解读</b>：干将属于中等偏上炮台法师，顶端局不用看（出场率低、胜率波动），但大众对局稳定。S44 大部分输出法师可提前出贤者之书替代博学者之怒，中期性价比更高。他不吃蓝buff也能靠圣杯永动，是少数"瞄不准也能玩"的炮台——质量不行就堆量。</div>
