<p>峡谷独有的"命运回溯"英雄：二技能在敌我之间切换远程/近战形态，大招展开领域后把自己（甚至己方防御塔）回溯到 5 秒前的状态——远程形态 poke 消耗，近战形态回复续航，大招读条回溯规避致命伤害，是"永远猜不到你下一步"的复合型战士。</p>
