<div class="skill"><div class="name">一技能·汇流为一<span class="tag">控制/增益</span></div><div class="desc">汇集"流"对附近敌人造成 <code>100~200(+25%额外法攻)</code> 伤害并击退（无硬控），自身获得 <code>150~300(+4%额外生命)</code> 回复与 5 层"流"，同时减少二/三技能 <code>50% 冷却</code>；附近友军与小兵获得回复（最高100%）和"流"（最多9层）。</div><div class="note">CD 12.5→10s。开团前先丢一次给二/三大招对半减 CD，收益极大。</div></div>
