<div class="skill"><div class="name">被动·隐介藏形<span class="tag">龙魂印记</span></div><div class="desc">最后两次技能的元素龙魂附于主副剑指：主剑指100%物攻物伤，副剑指对其他目标35%~70%物攻；技能叠加龙魂印记（至多3层）并获得1次强化普攻——消耗所有印记驱使龙魂冲击（每层多1段攻击，重复命中后续减半），效果随主剑指龙魂属性变化。切换元素时优先保留相同龙魂。</div><div class="note">核心输出循环：技能→叠3层→强化普攻，主剑指尽量挂火。</div></div>
