<div class="skill"><div class="name">三技能·狂兽血性<span class="tag">变身/团控</span></div><div class="desc">怒吼形成狂风通路，获得 <code>1700+35%额外生命</code> 护盾（15秒）+ 霸体和无敌 <code>1.25秒</code>；造成 <code>600+150%额外物理攻击</code> 伤害+击退，末端敌人 <code>眩晕1.5秒</code>；狂风中获 <code>50%移速</code>；真身普攻额外 <code>220+65%额外物理攻击</code>；真身结束时自动触发画地为牢。</div><div class="note">CD 30→24；狂意未满时开大控制距离大幅缩短，务必攒满再开。</div></div>
